      // Drag to move the yard. Bugs live in it: they run from the pointer, and a press catches one.
      const dogs = [...stage.querySelectorAll(".dog")], room = Math.max(0, (box.w - innerWidth) / 2), N = 7;
      const tally = el("p", "label tally");
      // A coarse map of where the dog stands, in the middle third of the art. Bugs stay off it.
      const onDog = (x, y) => { const u = x / box.w * 3 - 1, v = y / box.h; return u >= 0 && u < 1 && v >= 0 && v < 1 && DOG_MAP[(v * 45 | 0) * 44 + (u * 44 | 0)] === "1"; };
